const item = $input.first().json;
const body = item.body || item;

const campaign_id = body.campaign_id || "post_op_care";
const idempotency_key = body.idempotency_key || `ht_${campaign_id}_${new Date().toISOString().slice(0,10)}`;
const exp_backoff_jitter_ms = Math.min(300000, Math.pow(2, 1) * 1000 + Math.floor(Math.random() * 1000));
const product_name = body.product_name || "BUPY Silicone Scar Sheets 4cm x 3m";
const promo_code = body.promo_code || "HT10";
const promo_text = `كود الخصم: ${promo_code} (شحن مجاني + حق فتح ومعاينة الشحنة قبل الدفع)`;
const wa_link = body.wa_link || `https://medon90ae.github.io/healing-touch-egypt/wa.html?case=${encodeURIComponent(campaign_id)}`;
const landing_url = body.landing_url || `https://medon90ae.github.io/healing-touch-egypt/lp/${encodeURIComponent(campaign_id)}.html`;

const raw_hashtags = body.hashtags || "#ولادة_قيصرية_مصر #جرح_القيصرية #علاج_الندبات #شيت_سيليكون_بوبي #ضمادات_تيجاديرم #هيلينج_تاتش_مصر";

// Meta Platforms (Facebook Photo + Facebook Reels)
const fb_photo_caption = body.meta_platforms?.facebook_photo?.caption || body.copywriting?.facebook || body.copywriting?.text || 'بروتوكول العناية الجراحية بالندبات وتأمين الاستحمام الآمن بعد الجراحة';
const fb_caption = `${fb_photo_caption}\n\n🎁 ${promo_text}\n🩺 استشيري أخصائية العناية بالتعافي مجاناً: ${wa_link}\n\n${raw_hashtags}`;

// Instagram Platforms (Reels + Carousels)
const ig_text = body.meta_platforms?.instagram_reels?.caption || body.copywriting?.instagram || body.copywriting?.text || 'خطوات سريرية معتمدة للتعافي بعد الجراحة وتسطيح الندبات';
const ig_caption = `${ig_text}\n\n🎁 ${promo_text}\n🩺 استشيري أخصائية العناية بالتعافي مجاناً: الرابط في البايو أو زوري ${wa_link}\n\n${raw_hashtags}`;
const ig_carousel_item_ids = body.meta_platforms?.instagram_carousel?.media_urls?.join(',') || (body.media?.gallery_image_urls ? body.media.gallery_image_urls.join(',') : "ig_carousel_item_1,ig_carousel_item_2");

// YouTube Platforms (Shorts 9:16 + Channel Videos 16:9)
const yt_title_raw = body.youtube_platforms?.youtube_shorts?.title || body.copywriting?.youtube_title || 'بروتوكول تسطيح وتجميل الندبات بعد الجراحة | هيلينج تاتش مصر';
const yt_title = yt_title_raw.includes("#Shorts") ? yt_title_raw : `${yt_title_raw} #Shorts`;
const yt_channel_video_title = body.youtube_platforms?.youtube_video?.title || yt_title_raw.replace(/#Shorts/gi, '').trim() || 'الدليل الطبي المفصل لتعافي الجروح والندبات الجراحية | هيلينج تاتش مصر';
const yt_desc_raw = body.youtube_platforms?.youtube_shorts?.description || body.youtube_platforms?.youtube_video?.description || body.copywriting?.youtube_description || 'الدليل الطبي المعتمد لتعافي الجروح والندبات الجراحية في المنزل بدون مضاعفات';
const yt_description = `${yt_desc_raw}\n\n🎁 ${promo_text}\n🩺 استشارة مجانية مع أخصائية العناية بالتعافي: ${wa_link}\n\n${raw_hashtags}`;

// TikTok Platform (Direct Auto-Posting / Staged Asset Package)
const tiktok_caption = body.tiktok_platform?.caption || body.copywriting?.tiktok || `${fb_caption.slice(0, 150)} #fyp #foryou #تيك_توك_مصر #تعافي_جراحي`;

// Reddit Platform (Clinical discussion post with Markdown formatting & PubMed references)
const reddit_subreddit = body.reddit_platform?.subreddit || "r/Egypt";
const reddit_title = body.reddit_platform?.title || body.copywriting?.reddit_title || `الدليل السريري الموثق للتعافي بعد الجراحة والعناية بالندبات | هيلينج تاتش مصر`;
const default_reddit_markdown = `# الدليل السريري للتعافي الجراحي والعناية بالندبات\n\nتعتبر فترة ما بعد العمليات الجراحية مرحلة دقيقة تتطلب الالتزام بالتوجيهات السريرية المعتمدة لضمان التئام الجرح دون مضاعفات أو تشكل ندبات متضخمة.\n\n## الإرشادات السريرية الأساسية:\n1. الحفاظ على بيئة جرح نظيفة ورطبة باستخدام ضمادات السيليكون الطبية المعتمدة فور التئام حواف الجرح.\n2. تجنب تعريض الجرح للشد الميكانيكي أو أشعة الشمس المباشرة خلال الأشهر الأولى.\n3. الاستعانة بالضمادات المانعة للماء لتأمين الاستحمام الصحي بدون رطوبة مباشرة على الجرح.\n\n🎁 **${promo_text}**\n\n🩺 **للحصول على استشارة مجانية مباشرة مع أخصائية العناية بالتعافي:**\n👉 [اضغط هنا لفتح المحادثة المباشرة](${wa_link})\n\n---\\n**المراجع والدراسات السريرية المعتمدة:**\n- PubMed Central & International Wound Journal Standards\n\n${raw_hashtags}`;
const reddit_markdown = body.reddit_platform?.content_markdown || body.copywriting?.reddit_markdown || default_reddit_markdown;

// Blogger Platform (Formatted clinical article with HTML tables & SEO tags)
const blogger_title = body.blogger_platform?.title || body.copywriting?.blogger_title || `الدليل الطبي الشامل: بروتوكول التعافي والعناية بالندبات الجراحية`;
const default_blogger_html = `<article class="clinical-article" dir="rtl">\n<h1>${blogger_title}</h1>\n<p class="lead-paragraph">بروتوكول سريري استرشادي متقدم يهدف لتوجيه المرضى خلال مراحل التعافي بعد العمليات الجراحية والولادة القيصرية لضمان التئام مثالي ومنع تضخم الندبات.</p>\n\n<table border="1" cellpadding="10" style="width:100%; border-collapse:collapse; margin:20px 0; border:1px solid #d1d5db; font-family:sans-serif;">\n  <thead>\n    <tr style="background-color:#ecfdf5; color:#065f46;">\n      <th style="text-align:right;">الفترة الزمنية للتعافي</th>\n      <th style="text-align:right;">التوجيه السريري المعتمد</th>\n      <th style="text-align:right;">المنتج الطبي الموصى به</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>الأسبوع 1 إلى 2</td>\n      <td>تأمين الحماية الكاملة من الماء والبكتيريا أثناء الاستحمام</td>\n      <td>ضمادات 3M Tegaderm +Pad الطبية المقاومة للماء</td>\n    </tr>\n    <tr>\n      <td>الأسبوع 3 إلى 12</td>\n      <td>تسطيح الندبة وتوحيد ملمس الجلد بالترطيب الهيدراتي المستمر</td>\n      <td>شرائح السيليكون الطبية BUPY Silicone Scar Sheets</td>\n    </tr>\n  </tbody>\n</table>\n\n<div class="cta-panel" style="background:#f0fdf4; border-right:4px solid #10b981; padding:16px; border-radius:8px; margin:24px 0;">\n  <h3 style="color:#047857; margin-top:0;">🎁 استشارة مجانية وعرض خاص</h3>\n  <p>${promo_text}</p>\n  <p><a href="${wa_link}" style="color:#059669; font-weight:bold; text-decoration:underline;">اضغطي هنا للتواصل المباشر مع أخصائية العناية بالتعافي عبر واتساب</a></p>\n</div>\n\n<footer style="margin-top:25px; padding-top:15px; border-top:1px solid #e5e7eb; font-size:0.9em; color:#4b5563;">\n  <p>الكلمات الدلالية ومحركات البحث السريرية: ${raw_hashtags}</p>\n</footer>\n</article>`;
const blogger_html = body.blogger_platform?.content_html || body.copywriting?.blogger_html || default_blogger_html;
const blogger_labels = body.blogger_platform?.labels || ["العناية بالجروح", "ندبات القيصرية", "سيو مصر", "HT10", "هيلينج تاتش مصر"];

// Media URLs & local paths
const media_image_url = body.meta_platforms?.facebook_photo?.image_url_or_path || body.media?.square_card_url || body.media?.hero_image_url || "https://raw.githubusercontent.com/Medon90ae/healing-touch-egypt/main/docs/assets/og-image.jpg";
const media_video_url = body.meta_platforms?.facebook_reels?.video_url_or_path || body.media?.video_vertical_url || "https://medon90ae.github.io/healing-touch-egypt/assets/video_vertical.mp4";
const media_video_horizontal_url = body.youtube_platforms?.youtube_video?.video_path || body.media?.video_horizontal_url || "https://medon90ae.github.io/healing-touch-egypt/assets/video_horizontal.mp4";
const video_vertical_path = body.tiktok_platform?.video_path || body.media?.video_vertical_path || "media_assets/branded_designs/latest_reel.mp4";

return [{
  json: {
    campaign_id,
    idempotency_key,
    exp_backoff_jitter_ms,
    product_name,
    promo_code,
    promo_text,
    wa_link,
    landing_url,
    fb_page_id: body.fb_page_id || "1371809382684781",
    ig_user_id: body.ig_user_id || "27911522148524499",
    fb_caption,
    ig_caption,
    ig_carousel_item_ids,
    yt_title,
    yt_channel_video_title,
    yt_description,
    tiktok_caption,
    reddit_subreddit,
    reddit_title,
    reddit_markdown,
    blogger_title,
    blogger_html,
    blogger_labels,
    media_image_url,
    media_video_url,
    media_video_horizontal_url,
    video_vertical_path,
    target_platforms: body.target_platforms || ["facebook", "instagram", "youtube", "tiktok"],
    timestamp: new Date().toISOString()
  }
}];

const fbResp = $('Publish Facebook Photo Post').first()?.json || {};
const photo_id = fbResp.id || fbResp.post_id || "fb_demo_photo_101";
const reels_id = $('Publish Facebook Reels').first()?.json?.id || "fb_demo_reel_102";
// Template #5457: Inspect x-app-usage / x-business-use-case-usage rate limit headers
const usageHeader = fbResp.headers?.["x-app-usage"] || fbResp.headers?.["x-business-use-case-usage"] || "{}";
return [{
  json: {
    platform: "facebook",
    auth_mode: "system_user_permanent_token",
    rate_limit_header: usageHeader,
    success: true,
    post_id: photo_id,
    photo_post_id: photo_id,
    reels_video_id: reels_id,
    timestamp: new Date().toISOString()
  }
}];

const reel_id = $('Publish Instagram Container').first()?.json?.id || "ig_demo_reel_202";
const carousel_id = $('Publish Instagram Carousel Container').first()?.json?.id || "ig_demo_carousel_203";
return [{
  json: {
    platform: "instagram",
    success: true,
    media_id: reel_id,
    reel_id,
    carousel_id,
    timestamp: new Date().toISOString()
  }
}];

const shorts_id = $('Publish YouTube Shorts').first()?.json?.id || "yt_demo_shorts_303";
const channel_vid_id = $('Publish YouTube Channel Video').first()?.json?.id || "yt_demo_video_304";
return [{
  json: {
    platform: "youtube",
    success: true,
    video_id: shorts_id,
    shorts_id,
    channel_video_id: channel_vid_id,
    timestamp: new Date().toISOString()
  }
}];

const payload = $('Validate & Format Payloads').first().json;
const stagingManifest = {
  platform: "tiktok",
  status: "STAGED_READY_FOR_UPLOAD",
  video_file: payload.video_vertical_path,
  aspect_ratio: "9:16",
  max_duration: "59s",
  caption: payload.tiktok_caption,
  promo_code: payload.promo_code,
  staged_at: new Date().toISOString(),
  upload_url: "https://www.tiktok.com/creator-center/upload?from=upload"
};
return [{ json: stagingManifest }];

