const item = $input.first().json;
const poll_count = (item.poll_count || 0) + 1;
const max_polls = 10;
const status_code = String(item.status_code || "IN_PROGRESS").toUpperCase();
const is_terminal_error = status_code === 'ERROR' || status_code === 'EXPIRED';
const has_retries_left = poll_count < max_polls && !is_terminal_error;

return [{
  json: {
    ...item,
    poll_count,
    max_polls,
    status_code,
    is_terminal_error,
    has_retries_left,
    error_message: is_terminal_error
      ? `Instagram container failed with terminal status: ${status_code}`
      : (poll_count >= max_polls ? "Instagram container polling timed out after 10 attempts (100 seconds)" : null)
  }
}];

const item = $input.first().json;
return [{
  json: {
    platform: "instagram",
    success: false,
    status: item.is_terminal_error ? "FAILED" : "TIMED_OUT",
    status_code: item.status_code,
    error: item.error_message || "Instagram container processing failed",
    poll_count: item.poll_count,
    timestamp: new Date().toISOString()
  }
}];

const fb = $('Format Facebook Result').first()?.json || { success: false, status: 'skipped' };
const ig = $('Format Instagram Result').first()?.json || $('Format Instagram Error Result').first()?.json || { success: false, status: 'skipped' };
const yt = $('Format YouTube Result').first()?.json || { success: false, status: 'skipped' };
const tt = $('Format TikTok Result').first()?.json || { success: true, status: 'STAGED' };
const rd = $('Format Reddit Result').first()?.json || { success: false, status: 'skipped' };
const bl = $('Format Blogger Result').first()?.json || { success: false, status: 'skipped' };

return [{
  json: {
    success: true,
    event: "omnichannel_cross_post_completed",
    campaign_id: $('Validate & Format Payloads').first().json.campaign_id,
    promo_code: $('Validate & Format Payloads').first().json.promo_code,
    published_at: new Date().toISOString(),
    results: {
      facebook: fb,
      instagram: ig,
      youtube: yt,
      tiktok: tt,
      reddit: rd,
      blogger: bl
    }
  }
}];
